on conflict (chave) do update set dados = excluded.dados, origem = excluded.origem, em = now();

do $$
declare v jsonb;
begin
  if exists (select 1 from public.marcas where slug = 'pizzaria-pomerode') then
    v := private.importar_cardapio('pizzaria-pomerode', (select dados from private.cardapios_importados where chave = 'pizzaria-pomerode'));
    raise notice 'PIZZARIA POMERODE importada: %', v;
  else
    raise notice 'Marca pizzaria-pomerode não existe neste banco: nada importado.';
  end if;
end $$;

-- conferência: mostra o resultado no SQL Editor (as outras marcas continuam com a mesma contagem)
select m.slug as cardapio, c.nome as categoria, count(*) filter (where pm.ativo) as produtos_ativos
  from public.marcas m
  join public.produto_marcas pm on pm.marca_id = m.id
  join public.produtos p on p.id = pm.produto_id
  join public.setores c on c.id = p.setor_id
  join public.setor_marcas sm on sm.setor_id = c.id and sm.marca_id = m.id and sm.ativo
 where m.slug in ('pizzaria-pomerode', 'la-pizza')
 group by m.slug, c.nome, c.ordem order by m.slug desc, c.ordem;
